package com.cookly.actividades;
import android.os.Bundle;import android.view.Gravity;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;import com.cookly.almacenamiento.AlmacenToken;
public class ActividadPerfil extends AppCompatActivity{@Override public void onCreate(Bundle b){super.onCreate(b);LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setPadding(28,38,28,28);l.setBackgroundColor(0xffFFF8F3);TextView avatar=new TextView(this);avatar.setText("👩‍🍳");avatar.setTextSize(62);avatar.setGravity(Gravity.CENTER);l.addView(avatar,new LinearLayout.LayoutParams(-1,-2));TextView t=new TextView(this);t.setText("Mi perfil\n\nTu cocina, tus reglas");t.setTextSize(25);t.setTextColor(0xff241B18);t.setTypeface(null,1);t.setGravity(Gravity.CENTER);l.addView(t);TextView stats=new TextView(this);stats.setText("\n  0 recetas guardadas     0 creadas     0 favoritos\n\nCompleta tu perfil y empieza a crear tu propio recetario.");stats.setTextSize(16);stats.setPadding(8,30,8,30);l.addView(stats);Button cerrar=new Button(this);cerrar.setText("Cerrar sesión");cerrar.setOnClickListener(v->{new AlmacenToken(this).borrar();finishAffinity();});l.addView(cerrar);setContentView(l);}}
